# Let me try a completely different approach
# Maybe numbers just propagate ALLWAYS diagonally from their starting position

def solve_simple():
    # 8x8 output grid
    grid = [[0]*8 for _ in range(8)]

    # Place 2-squares exactly as in input
    # Top square: rows 1-2, cols 3-4
    for r in [1, 2]:
        for c in [3, 4]:
            grid[r][c] = 2
    # Bottom square: rows 5-6, cols 1-2
    for r in [5, 6]:
        for c in [1, 2]:
            grid[r][c] = 2

    # For each non-2 number in input, extend a diagonal ray in ALL 4 directions
    # until hitting boundary or a non-empty cell
    input_non2 = [
        (0, 2, 3), (0, 5, 8), (3, 2, 7), (3, 5, 6), (4, 0, 7),
        (4, 3, 6), (7, 0, 8), (7, 3, 3), (7, 5, 8), (7, 7, 3)
    ]

    directions = [(-1,-1), (-1,1), (1,-1), (1,1)]

    for (r, c, val) in input_non2:
        # Fill original position
        if grid[r][c] == 0:
            grid[r][c] = val

        # Extend in each direction
        for dr, dc in directions:
            rr, cc = r + dr, c + dc
            while 0 <= rr < 8 and 0 <= cc < 8 and grid[rr][cc] == 0:
                grid[rr][cc] = val
                rr, cc = rr + dr, cc + dc

    return grid

