def solve_final():
    def trace(rays, grid):
        for (r, c, val) in rays:
            # Place at start position
            if grid[r][c] == 0 or grid[r][c] == val:
                grid[r][c] = val
            else:
                # Different blocker at start
                pass

            # Extend in each direction
            for (dr, dc) in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
                rr, cc = r + dr, c + dc
                while 0 <= rr < 8 and 0 <= cc < 8:
                    if grid[rr][cc] == 2:
                        # Blocked by 2, stop
                        break
                    if grid[rr][cc] == 0:
                        # Empty, place value and continue
                        grid[rr][cc] = val
                        rr += dr
                        cc += dc
                    else:
                        # Blocked by different value, stop
                        break

        return grid

    grid = [[0]*8 for _ in range(8)]

    # Place 2-squares
